/** Execution result data model shared by the executor and reporters. */
import { resultId } from '../internal/ids.js';
import { keeps } from '../internal/recording-modes.js';
/**
 * Whether a status is a failure: the one question the runner asks of a
 * verdict before discarding a suite realm, ending a serial group, spending a
 * retry, or keeping a recording. A body that skipped itself is not one.
 */
export function isFailedStatus(status) {
    return status !== 'passed' && status !== 'skipped' && status !== 'flaky';
}
/**
 * Whether a serial member's record is a run of its body: every record but a
 * skip the runner wrote for a member it never started. A member that skipped
 * itself started its body.
 */
export function memberRan(member) {
    return member.status !== 'skipped' || member.skip?.cause === 'explicit';
}
/** Whether an attempt keeps its trace, by the rule its video follows too (`keeps`): a `test.fail` verdict, not what the body did. */
function keepsTrace(attempt) {
    return attempt.trace !== undefined && keeps(attempt.trace, attempt.status);
}
/** The report ids of the results that keep a trace page: those with an attempt that kept a trace; a serial member's attempts are its group's. */
export function tracedResultIds(results, serialGroups) {
    const groups = new Map(serialGroups.map((group) => [group.id, group]));
    const traced = new Set();
    for (const result of results) {
        const attempts = result.serialGroupId === undefined ? result.attempts : (groups.get(result.serialGroupId)?.attempts ?? []);
        if (attempts.some(keepsTrace))
            traced.add(resultId(result.test.id, result.target.name, result.agent, result.repeat));
    }
    return traced;
}
/**
 * The expected-failure mark of a result's verdict: its last attempt's. A
 * serial member is never marked.
 */
export function expectedFailureOf(result) {
    return result.attempts.at(-1)?.expectedFailure;
}
/** The cleanup-phase secondary errors of attempts whose cleanup failed. */
export function cleanupErrorsOf(attempts) {
    return attempts.flatMap((attempt) => attempt.cleanup === 'failed' ? attempt.secondaryErrors.filter((secondary) => secondary.phase === 'cleanup') : []);
}
/**
 * The failure a test's `test.skip(...)` followed: the last attempt that
 * failed before a skipped retry, or an error the skipped attempt kept beside
 * its skip. A soft failure before the skip fails its own attempt. Engine
 * cleanup diagnostics after the skip are not one. A serial member's attempts
 * live on its group, which `groupOf` looks up only for such a member.
 */
export function failureBeforeSkip(result, groupOf) {
    if (result.status !== 'skipped' || result.skip?.cause !== 'explicit')
        return undefined;
    const runs = result.serialGroupId === undefined
        ? result.attempts
        : (groupOf(result.serialGroupId)?.attempts ?? []).flatMap((attempt) => attempt.members
            .filter((member) => member.testId === result.test.id)
            .map((member) => ({ ...member, artifacts: attempt.artifacts })));
    for (const run of runs.toReversed()) {
        const error = run.error ?? run.secondaryErrors.find((secondary) => secondary.phase !== 'cleanup');
        if (error !== undefined)
            return { error, failure: run.failure, artifacts: run.artifacts };
    }
    return undefined;
}
/** Whether any skipped result followed a failure: what `failOnSkippedFailure` fails a run for. */
export function someSkippedAfterFailure(results, serialGroups) {
    const groups = new Map(serialGroups.map((group) => [group.id, group]));
    return results.some((result) => failureBeforeSkip(result, (id) => groups.get(id)) !== undefined);
}
/** Strips the live target from a result for transport. */
export function encodeResult(record) {
    const { target: _target, ...rest } = record;
    return rest;
}
